import { html } from 'htm/preact';
import { useState } from '@bpmn-io/properties-panel/preact/hooks';
import { useService } from 'bpmn-js-properties-panel';
import {
  getResourceMappings,
  addResourceMapping,
  removeResourceMapping
} from '../../services/MappingHelper.js';
import {
  FHIR_RESOURCE_TYPES,
  INTERACTIONS,
  DIRECTIONS,
  SEMANTIC_ROLES
} from '../../core/types.js';

export function FhirMappingListEntry(props) {
  const { element } = props;
  const moddle = useService('moddle');
  const modeling = useService('modeling');

  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyForm());
  const [, setRefresh] = useState(0);

  const bo = element.businessObject;
  const mappings = getResourceMappings(bo);

  function emptyForm() {
    return {
      resourceType: '', profile: '', interaction: 'create', direction: 'output',
      kePath: '', keRole: '', keFixed: ''
    };
  }

  function handleAdd() {
    const keyElements = [];
    if (form.kePath) {
      keyElements.push({
        path: form.kePath,
        semanticRole: form.keRole || undefined,
        fixedValue: form.keFixed || undefined
      });
    }
    addResourceMapping(bo, moddle, {
      resourceType: form.resourceType,
      profile: form.profile || undefined,
      interaction: form.interaction,
      direction: form.direction,
      keyElements
    });
    modeling.updateModdleProperties(element, bo, {});
    setForm(emptyForm());
    setShowForm(false);
    setRefresh(n => n + 1);
  }

  function handleRemove(i) {
    removeResourceMapping(bo, i);
    modeling.updateModdleProperties(element, bo, {});
    setRefresh(n => n + 1);
  }

  function u(field, value) { setForm({ ...form, [field]: value }); }

  return html`
    <div class="fhir-mappings">

      ${mappings.length > 0 && html`
        <div class="clinical-panel-list fhir-mapping-list">
          ${mappings.map((m, i) => html`
            <div class="clinical-panel-list-item fhir-mapping-item">
              <div class="clinical-panel-list-item__header fhir-mapping-item__header">
                <div class="clinical-panel-list-item__summary">
                  <span class="clinical-panel-list-item__title fhir-resource-badge">${m.resourceType}</span>
                  ${m.direction && html`<span class="clinical-panel-chip fhir-direction">${m.direction}</span>`}
                  ${m.interaction && html`<span class="clinical-panel-chip clinical-panel-chip--muted fhir-interaction">${m.interaction}</span>`}
                </div>
                <button
                  type="button"
                  class="clinical-panel-icon-button annotation-item__remove"
                  title="Remove mapping"
                  onClick=${() => handleRemove(i)}
                >×</button>
              </div>
              ${m.profile && html`
                <div class="bio-properties-panel-description fhir-mapping-item__profile">
                  Profile <code>${shortenUrl(m.profile)}</code>
                </div>
              `}
              ${(m.keyElements || []).length > 0 && html`
                <div class="clinical-panel-token-list">
                  ${(m.keyElements || []).map(ke => html`
                    <div class="clinical-panel-token-row fhir-mapping-item__key-element">
                      <code class="clinical-panel-code">${ke.path}</code>
                      ${ke.semanticRole && html`<span class="clinical-panel-chip badge badge--descriptive">${ke.semanticRole}</span>`}
                      ${ke.fixedValue && html`<span class="coding-display">= ${ke.fixedValue}</span>`}
                    </div>
                  `)}
                </div>
              `}
            </div>
          `)}
        </div>
      `}

      ${mappings.length === 0 && !showForm && html`
        <div class="bio-properties-panel-description annotation-empty">Keine FHIR-Mappings vorhanden.</div>
      `}

      ${!showForm && html`
        <div class="clinical-panel-actions">
          <button
            type="button"
            class="clinical-panel-add-button annotation-add-btn"
            onClick=${() => setShowForm(true)}
          >
            + FHIR-Mapping hinzufügen
          </button>
        </div>
      `}

      ${showForm && html`
        <div class="clinical-panel-editor annotation-form">
          <div class="bio-properties-panel-entry">
            <label class="bio-properties-panel-label">FHIR Ressourcentyp</label>
            <select class="bio-properties-panel-input" value=${form.resourceType} onChange=${e => u('resourceType', e.target.value)}>
              <option value="">– auswählen –</option>
              ${FHIR_RESOURCE_TYPES.map(r =>
                html`<option value=${r.type}>${r.label}</option>`
              )}
            </select>
          </div>

          <div class="bio-properties-panel-entry">
            <label class="bio-properties-panel-label">Profil-URL (optional)</label>
            <input
              class="bio-properties-panel-input bio-properties-panel-input-monospace"
              type="text"
              placeholder="https://mii.de/fhir/..."
              value=${form.profile}
              onInput=${e => u('profile', e.target.value)}
            />
          </div>

          <div class="bio-properties-panel-entry">
            <label class="bio-properties-panel-label">Interaktion</label>
            <select class="bio-properties-panel-input" value=${form.interaction} onChange=${e => u('interaction', e.target.value)}>
              ${INTERACTIONS.map(i => html`<option value=${i.value}>${i.label}</option>`)}
            </select>
          </div>

          <div class="bio-properties-panel-entry">
            <label class="bio-properties-panel-label">Richtung</label>
            <select class="bio-properties-panel-input" value=${form.direction} onChange=${e => u('direction', e.target.value)}>
              ${DIRECTIONS.map(d => html`<option value=${d.value}>${d.label}</option>`)}
            </select>
          </div>

          <div class="clinical-panel-section">
            <div class="clinical-panel-section__title">Key element</div>
            <div class="bio-properties-panel-description clinical-panel-section__description">
              Optional technical binding for a key FHIR field.
            </div>
            <div class="bio-properties-panel-entry">
              <label class="bio-properties-panel-label">FHIRPath</label>
              <input
                class="bio-properties-panel-input bio-properties-panel-input-monospace"
                type="text"
                placeholder="z.B. DiagnosticReport.status"
                value=${form.kePath}
                onInput=${e => u('kePath', e.target.value)}
              />
            </div>
            <div class="bio-properties-panel-entry">
              <label class="bio-properties-panel-label">Semantische Rolle</label>
              <select class="bio-properties-panel-input" value=${form.keRole} onChange=${e => u('keRole', e.target.value)}>
                <option value="">– keine –</option>
                ${SEMANTIC_ROLES.map(r => html`<option value=${r.value}>${r.label}</option>`)}
              </select>
            </div>
            <div class="bio-properties-panel-entry">
              <label class="bio-properties-panel-label">Fester Wert (optional)</label>
              <input
                class="bio-properties-panel-input"
                type="text"
                placeholder="z.B. final"
                value=${form.keFixed}
                onInput=${e => u('keFixed', e.target.value)}
              />
            </div>
          </div>

          <div class="clinical-panel-actions clinical-panel-actions--inline">
            <button
              type="button"
              class="clinical-panel-primary-button"
              onClick=${handleAdd}
              disabled=${!form.resourceType}
            >Hinzufügen</button>
            <button
              type="button"
              class="clinical-panel-secondary-button"
              onClick=${() => { setShowForm(false); setForm(emptyForm()); }}
            >Abbrechen</button>
          </div>
        </div>
      `}
    </div>
  `;
}

function shortenUrl(url) {
  if (!url) return '';
  const parts = url.split('/');
  return parts.length > 3 ? '…/' + parts.slice(-2).join('/') : url;
}
